// O Webhook entrega o corpo cru (binário) para que JSON malformado seja
// tratado aqui com HTTP 400, e não pelo parser nativo do n8n (que devolve 422).
const requiredFields = [
  'empresa',
  'cnpj',
  'email',
  'cep',
  'valor_estimado',
];

const resultado = (errors, payload = null) => [{
  json: { valid: errors.length === 0, errors, payload },
}];

let corpoCru = '';

if ($input.first().binary?.data) {
  const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  corpoCru = buffer.toString('utf8').replace(/^﻿/, '').trim();
}

// Corpo vazio vira objeto vazio: todos os campos aparecem como ausentes.
let body = {};

if (corpoCru.length > 0) {
  try {
    body = JSON.parse(corpoCru);
  } catch (error) {
    return resultado([{
      field: 'body',
      message: `JSON malformado: ${error.message}`
    }]);
  }
}

if (!body || typeof body !== 'object' || Array.isArray(body)) {
  return resultado([{
    field: 'body',
    message: 'O corpo da requisição deve ser um objeto JSON.'
  }]);
}

const errors = [];

for (const field of requiredFields) {
  if (!(field in body)) {
    errors.push({
      field,
      message: `Campo obrigatório ausente: ${field}.`
    });
  }
}

return resultado(errors, body);

const payload = $json.payload;

const errors = [];

// =========================
// 1. Sanitização de strings
// =========================
const empresa = typeof payload.empresa === 'string'
  ? payload.empresa.trim()
  : payload.empresa;

const email = typeof payload.email === 'string'
  ? payload.email.trim()
  : payload.email;

const cnpj = typeof payload.cnpj === 'string'
  ? payload.cnpj.trim()
  : payload.cnpj;

const cep = typeof payload.cep === 'string'
  ? payload.cep.trim()
  : payload.cep;

// =========================
// 2. Validação de empresa
// =========================
if (typeof empresa !== 'string' || empresa.length === 0) {
  errors.push({
    field: 'empresa',
    message: 'Empresa deve ser uma string não vazia.'
  });
}

// =========================
// 3. Normalização do CEP
// =========================
let cepNormalizado = '';

if (typeof cep === 'string') {
  cepNormalizado = cep.replace(/\D/g, '');
}

if (!/^\d{8}$/.test(cepNormalizado)) {
  errors.push({
    field: 'cep',
    message: 'CEP deve conter exatamente 8 dígitos.'
  });
}

// =========================
// 4. Normalização e validação CNPJ
// =========================
let cnpjNormalizado = '';

if (typeof cnpj === 'string') {
  cnpjNormalizado = cnpj.replace(/\D/g, '');
}

function validarCNPJ(cnpj) {
  if (!/^\d{14}$/.test(cnpj)) {
    return false;
  }

  // Rejeita sequências como 00000000000000, 11111111111111 etc.
  if (/^(\d)\1{13}$/.test(cnpj)) {
    return false;
  }

  // Primeiro dígito verificador
  let soma = 0;
  let peso = 5;

  for (let i = 0; i < 12; i++) {
    soma += Number(cnpj[i]) * peso;
    peso = peso === 2 ? 9 : peso - 1;
  }

  let resto = soma % 11;
  const dv1 = resto < 2 ? 0 : 11 - resto;

  if (dv1 !== Number(cnpj[12])) {
    return false;
  }

  // Segundo dígito verificador
  soma = 0;
  peso = 6;

  for (let i = 0; i < 13; i++) {
    soma += Number(cnpj[i]) * peso;
    peso = peso === 2 ? 9 : peso - 1;
  }

  resto = soma % 11;
  const dv2 = resto < 2 ? 0 : 11 - resto;

  return dv2 === Number(cnpj[13]);
}

if (!validarCNPJ(cnpjNormalizado)) {
  errors.push({
    field: 'cnpj',
    message: 'CNPJ inválido.'
  });
}

// =========================
// 5. Validação de e-mail
// =========================
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (
  typeof email !== 'string' ||
  !emailRegex.test(email)
) {
  errors.push({
    field: 'email',
    message: 'E-mail inválido.'
  });
}

// =========================
// 6. Validação do valor
// =========================
const valor = payload.valor_estimado;

if (
  typeof valor !== 'number' ||
  !Number.isFinite(valor) ||
  valor < 0
) {
  errors.push({
    field: 'valor_estimado',
    message: 'Valor estimado deve ser um número válido maior ou igual a zero.'
  });
}

// =========================
// Resultado
// =========================
return {
  valid: errors.length === 0,
  errors,
  payload: {
    empresa,
    cnpj: cnpjNormalizado,
    email,
    cep: cepNormalizado,
    valor_estimado: valor
  }
};

