  }
};

const dadosOriginais = $('Sanitizar e Validar Dados').item.json;

return {
  payload: dadosOriginais.payload,
  viacep: null,
  enriquecimento_incompleto: true,
  erro_enriquecimento: {
    servico: 'ViaCEP',
    mensagem: 'Não foi possível obter os dados do CEP.'
  }
};

const dadosOriginais = $('Sanitizar e Validar Dados').item.json;

const viaCEPExecutado = $('Consolidar Dados do ViaCEP').isExecuted;

const dadosViaCEP = viaCEPExecutado
  ? $('Consolidar Dados do ViaCEP').item.json.viacep
  : null;

const dadosBrasilAPI = $json;

const falhas = viaCEPExecutado ? [] : ['ViaCEP'];

return {
  payload: dadosOriginais.payload,
  viacep: dadosViaCEP,
  brasilapi: dadosBrasilAPI,
  enriquecimento_incompleto: falhas.length > 0,
  falhas_enriquecimento: falhas
};

const dadosOriginais = $('Sanitizar e Validar Dados').item.json;

const viaCEPExecutado = $('Consolidar Dados do ViaCEP').isExecuted;

const dadosViaCEP = viaCEPExecutado
  ? $('Consolidar Dados do ViaCEP').item.json.viacep
  : null;

const falhas = viaCEPExecutado ? ['BrasilAPI'] : ['ViaCEP', 'BrasilAPI'];

return {
  payload: dadosOriginais.payload,
  viacep: dadosViaCEP,
  brasilapi: null,
  enriquecimento_incompleto: true,
  falhas_enriquecimento: falhas
};

return {
  ...$json,
  rota: 'SUL_SUDESTE',
  roteamento: 'Direcionar para Time Comercial Sul/Sudeste'
};

return {
  ...$json,
  rota: 'GERAL',
  roteamento: 'Direcionar para Time Comercial Geral'
};

return {
  ...$json,
  rota: 'EXCECAO_OPERACIONAL',
  roteamento: 'Exceção operacional',
  erro: {
    tipo: 'LOCALIZACAO_NAO_DETERMINADA',
    mensagem: 'Não foi possível determinar a Unidade Federativa a partir do CEP. Lead registrado para triagem manual.'
  }
};

// Ponto único de convergência das três rotas (Sul/Sudeste, Geral e exceção):
// monta o registro que vai para o banco e o corpo da resposta HTTP.
const excecao = $json.rota === 'EXCECAO_OPERACIONAL';
const viacep = $json.viacep?.erro ? null : $json.viacep;
const brasilapi = $json.brasilapi ?? null;

const registro = {
  empresa: $json.payload.empresa,
  razao_social: brasilapi?.razao_social ?? null,
  cnpj: $json.payload.cnpj,
  email: $json.payload.email,
  cep: $json.payload.cep,
  valor_estimado: $json.payload.valor_estimado,
  municipio: viacep?.localidade ?? null,
  uf: viacep?.uf ?? null,
  uf_registro: brasilapi?.uf ?? null,
  situacao_cadastral: brasilapi?.descricao_situacao_cadastral ?? null,
  rota: $json.rota,
  roteamento: $json.roteamento,
  enriquecimento_incompleto: $json.enriquecimento_incompleto === true,
  falhas_enriquecimento: $json.falhas_enriquecimento ?? []
};

// 200 = roteado automaticamente; 202 = aceito e registrado, mas vai para triagem manual.
const httpStatus = excecao ? 202 : 200;

const resposta = {
  success: !excecao,
  status: httpStatus,
  roteamento: registro.roteamento,
  municipio: registro.municipio,
  uf: registro.uf,
  situacao_cadastral: registro.situacao_cadastral,
  razao_social: registro.razao_social,
  enriquecimento_incompleto: registro.enriquecimento_incompleto,
  falhas_enriquecimento: registro.falhas_enriquecimento
};

if (excecao) {
  resposta.erro = $json.erro;
}

return {
  http_status: httpStatus,
  registro,
  resposta,
  erro: $json.erro ?? null,
  dados_enriquecidos: {
    viacep: $json.viacep ?? null,
    brasilapi
  }
};

