const resultado = $('Montar Resultado do Lead').item.json;
const r = resultado.registro;
const leadId = $('Gravar Lead no Banco').item.json.id;

// parse_mode HTML do Telegram: dados vindos do formulário precisam ser escapados.
const esc = (valor) => String(valor ?? '—')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const cnpj = r.cnpj.replace(/^(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})$/, '$1.$2.$3/$4-$5');
const valor = Number(r.valor_estimado).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

const linhas = [
  r.rota === 'EXCECAO_OPERACIONAL' ? '⚠️ <b>Lead em exceção operacional</b>' : '🆕 <b>Novo lead B2B</b>',
  '',
  `🏢 <b>${esc(r.empresa)}</b>`,
  `🧾 CNPJ ${esc(cnpj)} · ${esc(r.situacao_cadastral)}`,
  `📍 ${esc(r.municipio)}/${esc(r.uf)}`,
  `💰 ${esc(valor)}`,
  `✉️ ${esc(r.email)}`,
  '',
  `➡️ <b>${esc(r.roteamento)}</b>`
];

if (r.enriquecimento_incompleto) {
  linhas.push(`⚠️ Enriquecimento incompleto: ${esc(r.falhas_enriquecimento.join(', '))}`);
}

if (resultado.erro) {
  linhas.push(`❗ ${esc(resultado.erro.mensagem)}`);
}

// Sem id = a gravação falhou (fail-open); o alerta deixa isso visível.
linhas.push(leadId
  ? `🆔 <code>${esc(leadId)}</code>`
  : '🗄️ ⚠️ Lead não foi gravado no banco');

return { texto: linhas.join('\n') };
